<script setup lang="ts">import {ref,onMounted} from 'vue';import axios from 'axios';const props=defineProps<{id:string}>();const data=ref<any>({participants:0,submitted:0});async function load(){const r=await axios.get(`/api/v1/teacher/exams/${props.id}/dashboard`);data.value=r.data}async function end(){if(confirm('Force end this exam and auto-submit remaining students?'))await axios.post(`/api/v1/teacher/exams/${props.id}/force-end`)}onMounted(load);setInterval(load,5000)</script>
<template><main><h1>Live Proctoring</h1><div class="cards"><b>Participants {{data.participants}}</b><b>Submitted {{data.submitted}}</b></div><p>Online/session details are refreshed from the server dashboard.</p><button class="danger" @click="end">Force end exam</button></main></template><style scoped>main{padding:32px;font:16px system-ui}.cards{display:flex;gap:30px;margin:20px 0}.danger{background:#b42318;color:white;padding:12px;border:0;border-radius:5px}</style>
